"use client"

import * as React from "react"

import { useComposedRefs } from "@/lib/0nlytype/refs"
import { cn } from "@/lib/utils"

type AvatarProps = Omit<React.ComponentProps<"span">, "children"> & {
  /** Who this is. It names the avatar, so say the person's name. */
  alt: string
  src?: string
  /** What shows without an image. Defaults to the first letter of alt (the given name, for fit), in italic. */
  fallback?: string
  size?: "s" | "m" | "l"
  /**
   * ring: a ring and the initial. monogram: the given initial in italic printed over the family
   * initial in a heavy narrow roman, as the poster's "has" crosses "It". fit: the given name alone,
   * set to fill one width, so a short name stands large and a long one small.
   */
  variant?: "ring" | "monogram" | "fit"
  /** This person is here now: the accent dot; in a monogram the italic takes the accent; fit hangs an accent full stop. */
  here?: boolean
  /** The overflow count at the end of a group ("+3"): set in the voice, not the italic. */
  count?: boolean
}

const words = (name: string) => name.trim().split(/\s+/)

/** Fit: measure the name at 100px in its own face and set the size that fills the box. Re-measures when the pair changes. */
function useFit(ref: React.RefObject<HTMLSpanElement | null>, text: string, on: boolean) {
  React.useLayoutEffect(() => {
    const el = ref.current
    if (!on || !el) return
    let live = true
    const ctx = document.createElement("canvas").getContext("2d")
    const fit = async () => {
      if (!live || !ctx) return
      const cs = getComputedStyle(el)
      const font = `${cs.fontStyle} ${cs.fontWeight} 100px ${cs.fontFamily}`
      try {
        await document.fonts.load(font, text)
      } catch {
        return // keep the fallback size if the face cannot load
      }
      if (!live) return
      ctx.font = font
      const w = ctx.measureText(text).width
      if (w) el.style.setProperty("--fit", `${(100 * el.clientWidth) / w}px`)
    }
    fit()
    // ponytail: the box is set in rem, so only the pair (on <html>) changes the fit; add a ResizeObserver if the box ever follows its container.
    const mo = new MutationObserver(fit)
    mo.observe(document.documentElement, { attributes: true, attributeFilter: ["data-pair", "data-scheme", "data-mode", "data-key"] })
    return () => { live = false; mo.disconnect() }
  }, [ref, text, on])
}

/** A person is a ring and their initial, in italic, since a name is theirs. */
function Avatar({ alt, src, fallback, size = "m", variant = "ring", here, count, className, ref, ...props }: AvatarProps) {
  const own = React.useRef<HTMLSpanElement>(null)
  const [given, ...rest] = words(alt)
  const fitted = variant === "fit" && !src && !count
  const label = fallback ?? (variant === "fit" ? given : alt.charAt(0).toUpperCase())
  useFit(own, label, fitted)

  let face: React.ReactNode = label
  if (src) {
    // eslint-disable-next-line @next/next/no-img-element -- a registry item is framework-agnostic
    face = <img src={src} alt="" />
  } else if (variant === "monogram" && !count) {
    const family = rest.at(-1)
    face = (
      <>
        <span className="ot-avatar-given">{(fallback ?? given).charAt(0).toUpperCase()}</span>
        {family && <span className="ot-avatar-family">{family.charAt(0).toUpperCase()}</span>}
      </>
    )
  }

  const composedRef = useComposedRefs(own, ref)
  return (
    <span
      ref={composedRef}
      data-slot="avatar"
      role="img"
      aria-label={here ? `${alt}, here now` : alt}
      data-size={size === "m" ? undefined : size}
      data-variant={variant === "ring" ? undefined : variant}
      dir={variant === "ring" ? undefined : "auto"} // the letters follow the name's own script, not the page's
      data-here={here || undefined}
      data-count={count || undefined}
      className={cn("ot-avatar", className)}
      {...props}
    >
      {face}
    </span>
  )
}

/** Avatars overlap, and step apart when pointed at; monograms stand side by side, and fitted names stack between hairlines. Its label says who the group is. */
function AvatarGroup({ className, ...props }: React.ComponentProps<"span">) {
  return <span data-slot="avatar-group" role="group" className={cn("ot-avatars", className)} {...props} />
}

export { Avatar, AvatarGroup, type AvatarProps }

@layer components {
  /* ── ot-avatar ── a person: a ring and their initial, in italic */
  .ot-avatar {
    --s: 2.75rem; position: relative; flex: none; display: inline-grid; place-items: center; width: var(--s); height: var(--s); border-radius: 50%;
    background: var(--ot-paper); box-shadow: inset 0 0 0 var(--ot-hairline) var(--ot-rule-strong);
    font-family: var(--ot-expression); font-style: italic; font-weight: 400; font-size: calc(var(--s) * 0.46); line-height: 1; color: var(--ot-ink);
  }
  .ot-avatar[data-size="s"] { --s: 1.75rem; }
  .ot-avatar[data-size="l"] { --s: 5rem; }
  .ot-avatar > img { width: 100%; height: 100%; border-radius: 50%; object-fit: cover; filter: grayscale(1); }
  .ot-avatar[data-here]::after { content: ""; position: absolute; inset-inline-end: 4%; bottom: 4%; width: max(7px, calc(var(--s) * 0.14)); aspect-ratio: 1; border-radius: 50%; background: var(--ot-accent); box-shadow: 0 0 0 2px var(--ot-paper); }
  .ot-avatar[data-count] { font-family: var(--ot-voice); font-style: normal; font-size: calc(var(--s) * 0.3); color: var(--ot-graphite); direction: ltr; unicode-bidi: isolate; }
  .ot-avatars { display: inline-flex; }
  .ot-avatars > .ot-avatar + .ot-avatar { margin-inline-start: calc(var(--s) * -0.28); transition: margin var(--ot-moderato) var(--ot-spiccato); }
  .ot-avatars:is(:hover, [data-force~="hover"]) > .ot-avatar + .ot-avatar { margin-inline-start: var(--ot-space-1); }

  /* ── monogram ── "It has to be design.": the given initial in italic printed over the family initial in a heavy narrow roman,
     cut out of it by a paper outline. Here now, the italic takes the accent, as "design." does. Pointed at, the italic steps off
     the roman so both letters read. */
  .ot-avatar:is([data-variant="monogram"], [data-variant="fit"]) { border-radius: 0; background: none; box-shadow: none; }
  .ot-avatar[data-variant="monogram"]:not([data-count]) { display: inline-flex; align-items: baseline; justify-content: center; width: auto; min-width: var(--s); font-size: calc(var(--s) * 0.62); line-height: 1; }
  .ot-avatar-given {
    position: relative; inset-inline-start: 0; z-index: 1; font-size: 1.36em; font-variation-settings: "opsz" 12; color: var(--ot-ink);
    -webkit-text-stroke: 0.07em var(--ot-paper); paint-order: stroke fill;
    transition: inset var(--ot-moderato) var(--ot-spiccato), color var(--ot-moderato);
  }
  .ot-avatar-family { margin-inline-start: -0.26em; font-family: var(--ot-voice); font-style: normal; font-weight: 800; font-stretch: 62%; letter-spacing: 0; color: var(--ot-ink); }
  .ot-avatar[data-variant="monogram"][data-here]::after { content: none; }
  .ot-avatar[data-variant="monogram"][data-here] .ot-avatar-given { color: var(--ot-accent); }
  .ot-avatar[data-variant="monogram"]:is(:hover, [data-force~="hover"]) .ot-avatar-given { inset-inline-start: -0.16em; inset-block-start: -0.06em; }
  .ot-avatars:has(> .ot-avatar[data-variant="monogram"]) { gap: calc(var(--s, 2.75rem) * 0.3); }
  .ot-avatars > .ot-avatar[data-variant="monogram"] + .ot-avatar { margin-inline-start: 0; }

  /* ── fit ── "Less is more.": the given name alone, set to fill one width (measured in its own face), so a short name stands
     large and a long one small. A group stacks them between hairlines. Here now hangs an accent full stop outside the measure. */
  .ot-avatar[data-variant="fit"] {
    display: block; width: calc(var(--s) * 1.8); height: auto; white-space: nowrap;
    font-size: min(var(--fit, calc(var(--s) * 0.5)), calc(var(--s) * 1.1)); line-height: 1; letter-spacing: 0;
  }
  .ot-avatar[data-variant="fit"][data-count] { font-size: var(--ot-pp); line-height: var(--ot-pp-lh); padding-top: var(--ot-space-2); }
  .ot-avatar[data-variant="fit"][data-here]::after { content: "." / ""; inset: auto; inset-inline-start: 100%; inset-block-end: 0; width: auto; aspect-ratio: auto; border-radius: 0; background: none; box-shadow: none; font-style: normal; color: var(--ot-accent); }
  .ot-avatars:has(> .ot-avatar[data-variant="fit"]) { display: inline-grid; justify-items: start; }
  .ot-avatars > .ot-avatar[data-variant="fit"] + .ot-avatar { margin-inline-start: 0; margin-top: var(--ot-space-2); padding-top: var(--ot-space-2); border-top: var(--ot-hairline) solid var(--ot-rule); width: calc(var(--s) * 1.8); }

  @media (forced-colors: active) {
    .ot-avatar-given { -webkit-text-stroke-color: Canvas; }
    .ot-avatar[data-variant="monogram"][data-here] .ot-avatar-given, .ot-avatar[data-variant="fit"][data-here]::after { color: Highlight; }
  }
}
